using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;
using Musikbox;
class AppThemeUiTests {
 static int count;static void Check(bool ok,string message){if(!ok)throw new Exception(message);count++;Console.WriteLine("OK "+message);}
 static IEnumerable<Control> All(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(Control nested in All(child))yield return nested;}}
 static DialogResult Message(MainView owner,Action<MessageView> action,MessageBoxButtons buttons){using(var timer=new Timer{Interval=30}){timer.Tick+=(s,e)=>{var view=Application.OpenForms.OfType<MessageView>().FirstOrDefault();if(view==null)return;timer.Stop();action(view);};timer.Start();return AppMessage.Show(owner,"Eine bewusste Entscheidung treffen.","Prüfung",buttons,MessageBoxIcon.Question);}}
 [STAThread]static void Main(string[] args){Directory.CreateDirectory(args[0]);Application.EnableVisualStyles();using(var view=new MainView(Path.Combine(args[0],"layout.json"))){new Controller(view,Path.Combine(args[0],"backups"));view.Show();Application.DoEvents();
  Check(view.FormBorderStyle==FormBorderStyle.None&&view.Controls.OfType<MetallicHeader>().Count()==1,"Hauptfenster erhält genau eine gemeinsame Design-Titelleiste");Check(view.Songs.FindForm()==view&&view.Tools.FindForm()==view&&view.Counts.Visible,"Listen, Befehle und Bestandsanzeige bleiben im Hauptfenster erreichbar");Check(view.Controls.OfType<MetallicHeader>().Single().Controls.OfType<ChromeButton>().Count()==3,"Hauptfenster besitzt Schließen, Maximieren und Minimieren");
  var chrome=view.Controls.OfType<MetallicHeader>().Single().Controls.OfType<ChromeButton>().ToArray();Check(chrome.Single(b=>b.AccessibleName=="Schließen").Left>chrome.Single(b=>b.Glyph=="Maximize").Left&&chrome.Single(b=>b.Glyph=="Maximize").Left>chrome.Single(b=>b.Glyph=="Minimize").Left,"Fensterknöpfe folgen der Windows-Reihenfolge Minimieren, Maximieren, Schließen");
  var menuRect=view.RectangleToClient(view.Tools.RectangleToScreen(view.Tools.ClientRectangle));var headerRect=view.Controls.OfType<MetallicHeader>().Single().Bounds;Check(menuRect.Top>=headerRect.Bottom,"Befehlsleiste liegt vollständig unter der Kopfzeile");
  var countRect=view.RectangleToClient(view.Counts.RectangleToScreen(view.Counts.ClientRectangle));Check(countRect.Bottom<=view.ClientSize.Height-4&&countRect.Top>=headerRect.Bottom,"Bestandszeile bleibt vollständig innerhalb des neuen Fensterrahmens: "+countRect+" / "+view.ClientSize);
  FormClosingEventHandler cancel=(s,e)=>e.Cancel=true;view.FormClosing+=cancel;view.Controls.OfType<MetallicHeader>().Single().Controls.OfType<ChromeButton>().Single(b=>b.AccessibleName=="Schließen").PerformClick();Check(!view.IsDisposed&&view.Visible,"Eigener Schließknopf respektiert FormClosing und Abbruch");view.FormClosing-=cancel;
  var song=new Song{Artist="Interpret",Title="Titel",Album="Album",Source="synthetisch.mp3"};
  using(var settings=new SettingsView(true,true))using(var tags=new TagEditorView(new List<Song>{song},"Thema"))using(var designer=new CoverDesignerView(CoverDesign.Default(),"Thema","Thema"))using(var fingerprint=new FingerprintSettingsView(new AcoustIdSettings()))using(var backup=new BackupRecoveryView(new List<ProjectBackupEntry>()))using(var covers=new CoverSearchView("Interpret","Titel",false)){
   foreach(var dialog in new ModernForm[]{settings,tags,designer,fingerprint,backup,covers}){dialog.Show(view);Application.DoEvents();Check(dialog.FormBorderStyle==FormBorderStyle.None&&dialog.Controls.OfType<MetallicHeader>().Count()==1,"Einheitlicher Rahmen für "+dialog.GetType().Name);Check(All(dialog).OfType<Button>().Any(b=>b.Visible)&&All(dialog).OfType<ChromeButton>().Any(b=>b.AccessibleName=="Schließen"),"Dialogbefehle und Schließknopf erreichbar: "+dialog.GetType().Name);dialog.Hide();}
   Check(settings.Tabs.DrawMode==TabDrawMode.OwnerDrawFixed&&backup.Items.BackColor==ModernTheme.Navy,"Registerkarten und Sicherungsliste folgen dem gemeinsamen Design");Check(fingerprint.ClientKey.UseSystemPasswordChar&&fingerprint.ClientKey.BackColor==ModernTheme.Navy,"Gestaltetes Zugangsfeld behält den Passwortschutz");
   view.PlayerPane.ShowPane();settings.Show();settings.Location=new Point(520,150);Application.DoEvents();using(var image=new Bitmap(1400,1000)){using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(0,0,0,0,image.Size);image.Save(Path.Combine(args[0],"app-theme.png"));}settings.Hide();
  }
  using(var fixedDialog=new ModernForm{Text="Fester Dialog",FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false,ClientSize=new Size(320,160)}){var input=new TextBox{Left=20,Top=15,Width=220,Text="unverändert"};fixedDialog.Controls.Add(input);fixedDialog.Show(view);Application.DoEvents();var screen=fixedDialog.RectangleToClient(input.RectangleToScreen(input.ClientRectangle));Check(input.Text=="unverändert"&&screen.Top>=fixedDialog.Controls.OfType<MetallicHeader>().Single().Bottom&&input.Visible,"Absolute Eingabefelder liegen unter der neuen Kopfzeile und behalten ihren Wert");Check(!All(fixedDialog).OfType<ResizeGrip>().Any(),"Fester Dialog bleibt ohne Größenänderungsgriff");fixedDialog.Text="Neuer Titel";Check(fixedDialog.Controls.OfType<MetallicHeader>().Single().Controls.OfType<Label>().Single().Text=="NEUER TITEL","Geänderte Dialogtitel aktualisieren die gestaltete Kopfzeile");fixedDialog.Close();}
  Check(Message(view,m=>All(m).OfType<Button>().Single(b=>b.Text=="Ja").PerformClick(),MessageBoxButtons.YesNo)==DialogResult.Yes,"Bestätigungsdialog liefert bei Ja weiterhin Yes");
  Check(Message(view,m=>((Button)m.CancelButton).PerformClick(),MessageBoxButtons.YesNo)==DialogResult.No,"Abbrechen einer Ja/Nein-Abfrage liefert No");
  Check(Message(view,m=>m.Controls.OfType<MetallicHeader>().Single().Controls.OfType<ChromeButton>().Single().PerformClick(),MessageBoxButtons.YesNo)==DialogResult.No,"Kreuz einer Bestätigungsabfrage bestätigt keine Änderung");
  Check(Message(view,m=>m.Close(),MessageBoxButtons.OK)==DialogResult.OK,"Schließen eines Hinweises liefert OK");view.Close();
 }Console.WriteLine("BESTANDEN: "+count+" appweite Design-/Dialogprüfungen unter Mono");}
}
